window.VARIANTS.push({id:1,name:'冒险手册',en:'THE ORIGINAL FIELD BOOK',color:'#7f8b6b',desc:'翻开一本亲手装订的手册，让角色从纸页间出发。',render(C,s){return `<div class="variant variant-1"><div class="book-topline"><span>THE WANDERER’S COMPANION</span><span>FIELD EDITION · 01</span></div><div class="adventure-book"><article class="book-leaf book-left"><div class="notebook-corner"></div><header class="book-title"><span class="book-emblem">✦</span><div><em>My Adventure.</em><span>我的冒险手册</span></div><span class="book-number">Nº 001</span></header><div class="portrait-page"><span class="portrait-margin">WANDER FAR · REMEMBER MUCH</span>${C.portrait()}<div class="portrait-note">带上好奇心，<br>其余的路上再找。</div><span class="passport-stamp">自由探索<br><small>EXPLORER</small></span></div>${C.identity()}<div class="page-bottom"><span>角色档案 / CHARACTER</span><span>1</span></div></article><article class="book-leaf book-right"><div class="page-label"><span>身体、直觉与一点好运</span><button data-action="roll" class="paper-dice">◇ 掷骰</button></div>${C.resources()}${C.section('天赋与本领','ATTRIBUTES',C.stats())}${C.section('随身行囊','PACK FOR THE UNKNOWN',C.inventory())}${C.traits()}<div class="page-bottom"><span>COC 7 · 车卡示例</span><span>2</span></div></article><div class="book-spine" aria-hidden="true"></div></div><div class="under-book"><span class="pencil-note">每个数字，都是故事的起点。</span><span>↓ 继续写下你的故事</span></div><div class="book-supplement">${C.section('练习过的事','SKILLS & CHECKS',C.skills())}${C.section('尚未写完的故事','THE STORY SO FAR',C.story())}</div></div>`;}});
